CREATE TABLE `polymorphs` (
  `name` varchar(45) NOT NULL,
  `note` varchar(45) DEFAULT '',
  `polyid` int(11) NOT NULL DEFAULT '1',
  `minlevel` int(11) NOT NULL DEFAULT '1',
  `weaponequip` int(11) NOT NULL DEFAULT '751',
  `armorequip` int(11) NOT NULL DEFAULT '4095',
  `isSkillUse` int(11) NOT NULL DEFAULT '1',
  `cause` int(11) NOT NULL DEFAULT '7',
  PRIMARY KEY (`name`)
) ENGINE=MyISAM AUTO_INCREMENT=12232 DEFAULT CHARSET=utf8;

